-- Read-only feasibility benchmark. SYSTEM sampling touches a small fraction of
-- blocks; pg_column_size estimates payload, not physical post-migration storage.
with sample as materialized (select * from public.token_metric_observations tablesample system (2) repeatable (42)), metadata as materialized (select row_number() over ()::bigint as metadata_id, d.* from (select distinct note,source_field,scope,provider_asset_id from sample) d), packed as materialized (select s.*, m.metadata_id, pg_column_size(row(s.id,s.token_id,s.chain_id,s.metric_id,s.provider_id,s.raw_record_id,s.value,s.window_days,s.status,s.observed_at,s.collected_at,null::text,null::text,s.created_at,null::text,null::text,s.mapping_id,s.excluded_reason,m.metadata_id)) as compact_bytes, to_jsonb(s) - array['note','source_field','scope','provider_asset_id'] as core from sample s join metadata m on s.note is not distinct from m.note and s.source_field is not distinct from m.source_field and s.scope is not distinct from m.scope and s.provider_asset_id is not distinct from m.provider_asset_id), verified as (select p.*, p.core || jsonb_build_object('note',m.note,'source_field',m.source_field,'scope',m.scope,'provider_asset_id',m.provider_asset_id) as reconstructed from packed p join metadata m using(metadata_id)) select jsonb_build_object('sample_rows',(select count(*) from sample),'distinct_metadata',(select count(*) from metadata),'roundtrip_mismatches',(select count(*) from verified v where v.reconstructed is distinct from (to_jsonb(v) - array['metadata_id','compact_bytes','core','reconstructed'])),'original_row_bytes',(select sum(pg_column_size(s)) from sample s),'compact_row_bytes',(select sum(compact_bytes) from packed),'dictionary_row_bytes',(select sum(pg_column_size(m)) from metadata m),'estimated_total_rows',(select reltuples::bigint from pg_class where oid='public.token_metric_observations'::regclass)) as prototype;
